function today(){return new Date().toISOString().split("T")[0]}
function money(value){return `KSh ${Number(value||0).toLocaleString()}`}
function toggleCompactView(){document.body.classList.toggle('compact-view');localStorage.setItem('labourforce_compact_view',document.body.classList.contains('compact-view')?'1':'0')}
if(localStorage.getItem('labourforce_compact_view')==='1')document.body.classList.add('compact-view');
function esc(value){return String(value??"").replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function showToast(message){const t=document.getElementById("toast");t.textContent=message;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2500)}
function formatDateTime(value){if(!value)return "—";return new Date(value).toLocaleString("en-KE",{dateStyle:"medium",timeStyle:"short"})}
function clientById(id){return clients.find(c=>Number(c.id)===Number(id))}
function requestById(id){return labourRequests.find(r=>Number(r.id)===Number(id))}
function requestNo(){let max=0;labourRequests.forEach(r=>{const m=String(r.requestNo||"").match(/^LR-(\d+)$/);if(m)max=Math.max(max,Number(m[1]))});return `LR-${String(max+1).padStart(4,"0")}`}
function employeeNo(){let max=0;workers.forEach(w=>{const m=String(w.employeeNo||"").match(/^WK(\d+)$/i);if(m)max=Math.max(max,Number(m[1]))});return `WK${String(max+1).padStart(3,"0")}`}
function currentRoleName(){return String(window.lfCurrentRole||'').toLowerCase();}
function canManageWorkerMasterData(){const role=currentRoleName();return ['super_admin','administrator','accounts','hr','human_resources'].includes(role);}
function canCaptureAttendance(){const role=currentRoleName();return ['super_admin','administrator','accounts','team_leader'].includes(role) || !role;}
function getDayRecord(date){if(!attendance[date])attendance[date]={status:"draft",submitted:false,submittedAt:null,approved:false,approvedAt:null,records:{}};if(!attendance[date].records)attendance[date].records={};return attendance[date]}
function getAttendance(date,id){const day=getDayRecord(date);if(!day.records[id])day.records[id]={status:"pending",hours:0,overtime:0};return day.records[id]}
function ensureJtsRosterForDate(date){const active=workers.filter(w=>w.active);if(!active.length)return;active.forEach(w=>{const record=getAttendance(date,w.id);if(!record.status)record.status="pending";record.hours=Number(record.hours||0);record.overtime=Number(record.overtime||0);});}
function showPage(id,button){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));const page=document.getElementById(id);if(!page)return;page.classList.add('active');document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));if(button)button.classList.add('active');const titles={dashboard:'Dashboard',requests:'Labour Requests',attendance:'Daily Attendance','jts':'JTS Daily Roll Call','jts-history':'JTS History & Disputes','jts-payroll':'JTS Payroll Review',approval:'Supervisor Approval',workers:'Workers',clients:'Clients / Mother Companies',departments:'Departments',payroll:'Payroll',users:'Users & Access',reports:'Reports'};document.getElementById('pageTitle').textContent=titles[id]||id;if(id==='dashboard')renderDashboard();if(id==='requests')renderRequests();if(id==='attendance')renderAttendance();if(id==='jts')renderJtsAttendance();if(id==='jts-history')renderJtsHistory();if(id==='jts-payroll')renderJtsPayroll();if(id==='approval')renderApproval();if(id==='workers')renderWorkers();if(id==='clients')renderClients();if(id==='departments')renderDepartments();if(id==='payroll')renderPayroll();if(id==='users'&&typeof renderUsers==='function')renderUsers();if(id==='reports')renderReports()}
function populateFilters(){const ids=["departmentFilter","workerDepartmentFilter","approvalDepartment","requestDepartment","deploymentDepartment"];ids.forEach(id=>{const el=document.getElementById(id);if(!el)return;const current=el.value;el.innerHTML=(id.includes("Filter")||id==="approvalDepartment")?'<option value="all">All Departments</option>':'';if(id==="requestDepartment"||id==="deploymentDepartment")el.innerHTML="";departments.forEach(d=>el.innerHTML+=`<option value="${esc(d.name)}">${esc(d.name)}</option>`);if([...el.options].some(o=>o.value===current))el.value=current});const wd=document.getElementById("workerDepartment");if(wd){const current=wd.value;wd.innerHTML="";departments.forEach(d=>wd.innerHTML+=`<option value="${esc(d.name)}">${esc(d.name)}</option>`);if([...wd.options].some(o=>o.value===current))wd.value=current}const parent=document.getElementById("departmentParent");if(parent){parent.innerHTML='<option value="">None</option>';departments.forEach(d=>parent.innerHTML+=`<option value="${esc(d.name)}">${esc(d.name)}</option>`)}populateClientSelects()}
function populateClientSelects(){const ids=["requestClient","deploymentClient"];ids.forEach(id=>{const el=document.getElementById(id);if(!el)return;const current=el.value;el.innerHTML="<option value=''>Select client</option>";clients.filter(c=>c.active).forEach(c=>el.innerHTML+=`<option value="${c.id}">${esc(c.name)}</option>`);if([...el.options].some(o=>o.value===current))el.value=current});const req=document.getElementById("deploymentRequest");if(req){const current=req.value;req.innerHTML='<option value="">Direct deployment — no request</option>';labourRequests.filter(r=>!["Cancelled","Completed"].includes(r.status)).forEach(r=>{const c=clientById(r.clientId);req.innerHTML+=`<option value="${r.id}">${esc(r.requestNo)} — ${esc(c?.name||"Unknown client")}</option>`});if([...req.options].some(o=>o.value===current))req.value=current}}
function renderDashboard(){const date=today();let worked=0,missing=0;workers.filter(w=>w.active).forEach(w=>{const r=getAttendance(date,w.id);if(r.status==="worked")worked++;if(r.status==="pending")missing++});document.getElementById("dashboardWorkers").textContent=workers.filter(w=>w.active).length;document.getElementById("dashboardRequests").textContent=labourRequests.filter(r=>r.status==="Pending").length;document.getElementById("dashboardWorked").textContent=worked;document.getElementById("dashboardMissing").textContent=missing;const ta=document.getElementById("dashboardAttendance");ta.innerHTML="";workers.filter(w=>w.active).slice(0,10).forEach(w=>{const r=getAttendance(date,w.id);const label=r.status==="worked"?"Worked":r.status==="absent"?"Absent":"Missing";const cls=r.status==="worked"?"status-worked":r.status==="absent"?"status-absent":"status-missing";ta.innerHTML+=`<tr><td><strong>${esc(w.name)}</strong></td><td>${esc(w.department)}</td><td>${esc(w.classification)}</td><td>${money(w.rate)}</td><td><span class="status ${cls}">${label}</span></td></tr>`});const rt=document.getElementById("dashboardRequestsTable");rt.innerHTML="";labourRequests.slice(-5).reverse().forEach(r=>{const c=clientById(r.clientId);rt.innerHTML+=`<tr><td><strong>${esc(r.requestNo)}</strong></td><td>${esc(c?.name||"—")}</td><td>${esc(r.department)}</td><td>${r.workersRequired}</td><td>${esc(r.startDate)}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td></tr>`});saveData()}
function renderFuturisticDashboard(){const date=document.getElementById('dashboardDate')?.value||today(),search=(document.getElementById('dashboardWorkerSearch')?.value||'').toLowerCase().trim(),designation=document.getElementById('dashboardDesignationFilter')?.value||'all',department=document.getElementById('dashboardDepartmentFilter')?.value||'all',active=workers.filter(w=>w.active),records=active.map(w=>({w,r:getAttendance(date,w.id)})),present=records.filter(x=>x.r.status==='present'||x.r.status==='worked'),absent=records.filter(x=>x.r.status==='absent'),pending=records.filter(x=>x.r.status==='pending'),filtered=present.filter(x=>(designation==='all'||x.w.designation===designation)&&(department==='all'||x.w.department===department)&&(!search||[x.w.name,x.w.idNumber,x.w.employeeNo,x.w.designation,x.w.department].some(v=>String(v||'').toLowerCase().includes(search))));document.getElementById('dashboardWorkers').textContent=active.length;document.getElementById('dashboardRequests').textContent=labourRequests.filter(r=>r.status==='Pending').length;document.getElementById('dashboardWorked').textContent=present.length;document.getElementById('dashboardMissing').textContent=pending.length;const fill=(id,values,label)=>{const select=document.getElementById(id);if(!select)return;const current=select.value;select.innerHTML=`<option value="all">All ${label}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(values.includes(current))select.value=current};fill('dashboardDesignationFilter',[...new Set(active.map(w=>w.designation).filter(Boolean))].sort(),'designations');fill('dashboardDepartmentFilter',[...new Set(active.map(w=>w.department).filter(Boolean))].sort(),'departments');const groupMap={};present.forEach(({w})=>{const key=w.designation||'Unassigned';groupMap[key]=(groupMap[key]||0)+1;});const groups=document.getElementById('dashboardDesignationGroups');if(groups)groups.innerHTML=Object.entries(groupMap).sort((a,b)=>b[1]-a[1]).map(([name,count])=>`<button class="designation-pulse" onclick="document.getElementById('dashboardDesignationFilter').value=${JSON.stringify(name)};renderFuturisticDashboard()"><span>${esc(name)}</span><strong>${count}</strong><small>present</small></button>`).join('')||'<div class="empty">No present workers recorded for this date.</div>';const table=document.getElementById('dashboardAttendance');if(table)table.innerHTML=filtered.map(({w,r})=>`<tr><td><strong>${esc(w.name)}</strong></td><td>${esc(w.idNumber||w.employeeNo||'—')}</td><td>${esc(w.designation||'Unassigned')}</td><td>${esc(w.department||'—')}</td><td>${Number(r.hours||0)}</td><td>${Number(r.overtime||0)}</td><td><span class="status status-worked">Present</span></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No present workers match the current view.</div></td></tr>';const rt=document.getElementById('dashboardRequestsTable');if(rt){rt.innerHTML='';labourRequests.slice(-5).reverse().forEach(r=>{const c=clientById(r.clientId);rt.innerHTML+=`<tr><td><strong>${esc(r.requestNo)}</strong></td><td>${esc(c?.name||'—')}</td><td>${esc(r.department)}</td><td>${r.workersRequired}</td><td>${esc(r.startDate)}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td></tr>`});}}
function portalStatus(record){return record.status==='worked'?'present':record.status||'pending'}
function renderSupervisorPortal(){const date=document.getElementById('supervisorDate')?.value||today(),search=(document.getElementById('supervisorSearch')?.value||'').toLowerCase().trim(),designation=document.getElementById('supervisorDesignation')?.value||'all',status=document.getElementById('supervisorStatus')?.value||'all',rows=workers.filter(w=>w.active).map(w=>({w,r:getAttendance(date,w.id)})).filter(({w,r})=>(designation==='all'||w.designation===designation)&&(status==='all'||portalStatus(r)===status)&&(!search||[w.name,w.idNumber,w.employeeNo].some(v=>String(v||'').toLowerCase().includes(search))));const all=workers.filter(w=>w.active).map(w=>getAttendance(date,w.id)),count=(value)=>all.filter(r=>portalStatus(r)===value).length;const summary=document.getElementById('supervisorSummary');if(summary)summary.innerHTML=`<div class="summary-card"><strong>${all.length}</strong><span>Expected</span></div><div class="summary-card"><strong>${count('present')}</strong><span>Present</span></div><div class="summary-card"><strong>${count('absent')}</strong><span>Absent</span></div><div class="summary-card"><strong>${count('pending')}</strong><span>Pending</span></div>`;const fill=(id,values,label)=>{const el=document.getElementById(id);if(!el)return;const current=el.value;el.innerHTML=`<option value="all">All ${label}</option>`+[...new Set(values.filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(values.includes(current))el.value=current};fill('supervisorDesignation',workers.map(w=>w.designation),'designations');const table=document.getElementById('supervisorTable');if(table)table.innerHTML=rows.map(({w,r})=>`<tr><td><input class="supervisor-select" type="checkbox" value="${w.id}"></td><td><strong>${esc(w.name)}</strong></td><td>${esc(w.idNumber||w.employeeNo||'—')}</td><td>${esc(w.designation||'—')}</td><td>${esc(w.department||'—')}</td><td><span class="status status-${portalStatus(r)==='present'?'worked':portalStatus(r)==='absent'?'absent':'pending'}">${esc(portalStatus(r))}</span></td><td>${Number(r.hours||0)}</td><td>${Number(r.overtime||0)}</td><td><button class="secondary" onclick="editSupervisorRecord(${w.id},'${date}')">Details</button></td></tr>`).join('')||'<tr><td colspan="9"><div class="empty">No workers match this view.</div></td></tr>';}
function bulkSupervisorStatus(status){const date=document.getElementById('supervisorDate')?.value||today(),ids=[...document.querySelectorAll('.supervisor-select:checked')].map(input=>Number(input.value));if(!canCaptureAttendance()){showToast('You do not have attendance permission.');return;}if(!ids.length){showToast('Select workers first.');return;}ids.forEach(id=>setJtsStatus(date,id,status==='present'?'present':'absent'));renderSupervisorPortal();showToast(`Marked ${ids.length} worker(s) ${status}.`);}
function editSupervisorRecord(workerId,date){if(!canCaptureAttendance())return;const record=getAttendance(date,workerId),hours=prompt('Regular hours:',String(record.hours||9));if(hours===null)return;const overtime=prompt('Overtime hours:',String(record.overtime||0));if(overtime===null)return;record.status='present';record.hours=Math.min(24,Math.max(0,Number(hours)||0));record.overtime=Math.max(0,Number(overtime)||0);record.remarks=prompt('Remarks (optional):',record.remarks||'')||'';localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderSupervisorPortal();}
function submitSupervisorAttendance(){const date=document.getElementById('supervisorDate')?.value||today(),day=getDayRecord(date);if(day.submitted||day.approved){showToast('This attendance copy is already final.');return;}const marked=workers.filter(w=>w.active).filter(w=>{const r=day.records?.[w.id];return r&&(r.status==='present'||r.status==='worked'||r.status==='absent')});if(!marked.length){showToast('Mark at least one worker before submitting.');return;}if(!confirm(`Submit ${marked.length} marked worker(s) as the final copy for ${date}?`))return;day.submitted=true;day.status='submitted';day.submittedAt=new Date().toISOString();localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderSupervisorPortal();showToast('Final attendance copy submitted.');}
function supervisorSelectedIds(){return [...document.querySelectorAll('.supervisor-select:checked')].map(input=>Number(input.value));}
function editSelectedSupervisor(){const date=document.getElementById('supervisorDate')?.value||today(),ids=supervisorSelectedIds();if(ids.length!==1){showToast('Select one marked worker to edit.');return;}editSupervisorRecord(ids[0],date);}
function cancelSelectedSupervisor(){const date=document.getElementById('supervisorDate')?.value||today(),ids=supervisorSelectedIds(),day=getDayRecord(date);if(day.submitted||day.approved){showToast('Final attendance cannot be cancelled.');return;}if(!ids.length){showToast('Select marked workers first.');return;}ids.forEach(id=>{const record=day.records?.[id];if(record){record.status='pending';record.hours=0;record.overtime=0;record.remarks='';}});localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderSupervisorPortal();showToast(`Cancelled ${ids.length} marked worker(s).`);}
function renderSupervisorPortalSearchFirst(){const date=document.getElementById('supervisorDate')?.value||today(),query=(document.getElementById('supervisorSearch')?.value||'').trim().toLowerCase(),day=getDayRecord(date),marked=workers.filter(w=>{const r=day.records?.[w.id];return w.active&&r&&(r.status==='present'||r.status==='worked'||r.status==='absent')}),results=query.length<2?[]:workers.filter(w=>w.active&&!marked.some(item=>item.id===w.id)&&[w.name,w.idNumber,w.employeeNo].some(value=>String(value||'').toLowerCase().includes(query))).slice(0,15),all=workers.filter(w=>w.active),summary=document.getElementById('supervisorSummary');if(summary){const present=marked.filter(w=>['present','worked'].includes(day.records[w.id]?.status)).length,absent=marked.filter(w=>day.records[w.id]?.status==='absent').length;summary.innerHTML=`<div class="summary-card"><strong>${all.length}</strong><span>Expected</span></div><div class="summary-card"><strong>${present}</strong><span>Marked present</span></div><div class="summary-card"><strong>${absent}</strong><span>Marked absent</span></div><div class="summary-card"><strong>${marked.length}</strong><span>Marked total</span></div>`;}const searchBox=document.getElementById('supervisorSearchResults');if(searchBox)searchBox.innerHTML=query.length<2?'':results.map(w=>`<button class="worker-search-result" onclick="markSupervisorPresent(${w.id})"><span><strong>${esc(w.name)}</strong><small>${esc(w.idNumber||w.employeeNo||'')} · ${esc(w.designation||'')}</small></span><b>Mark present</b></button>`).join('')||'<div class="empty">No matching unmarked worker.</div>';const table=document.getElementById('supervisorTable');if(table)table.innerHTML=marked.map(w=>{const r=day.records[w.id],state=portalStatus(r);return `<tr><td><input class="supervisor-select" type="checkbox" value="${w.id}"></td><td><strong>${esc(w.name)}</strong></td><td>${esc(w.idNumber||w.employeeNo||'')}</td><td>${esc(w.designation||'')}</td><td>${esc(w.department||'')}</td><td><span class="status status-${state==='present'?'worked':state==='absent'?'absent':'pending'}">${esc(state)}</span></td><td>${Number(r.hours||0)}</td><td>${Number(r.overtime||0)}</td><td><button class="secondary" onclick="editSupervisorRecord(${w.id},'${date}')">Edit</button> <button class="danger" onclick="cancelSupervisorRecord(${w.id},'${date}')">Cancel</button></td></tr>`}).join('')||'<tr><td colspan="9"><div class="empty">Search for a worker above to begin marking attendance.</div></td></tr>';}
function markSupervisorPresent(workerId){const date=document.getElementById('supervisorDate')?.value||today(),record=getAttendance(date,workerId);if(getDayRecord(date).submitted||getDayRecord(date).approved){showToast('This attendance copy is final.');return;}record.status='present';record.hours=9;record.overtime=0;localStorage.setItem('labourforce_attendance_dirty','1');saveData();document.getElementById('supervisorSearch').value='';renderSupervisorPortal();showToast('Worker marked present.');}
function cancelSupervisorRecord(workerId,date){const day=getDayRecord(date);if(day.submitted||day.approved){showToast('Final attendance cannot be cancelled.');return;}const record=day.records?.[workerId];if(record){record.status='pending';record.hours=0;record.overtime=0;record.remarks='';localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderSupervisorPortal();}}
const baseSupervisorPortal=renderSupervisorPortal;
function renderSupervisorAttendanceOnly(){const date=document.getElementById('supervisorDate')?.value||today(),query=(document.getElementById('supervisorSearch')?.value||'').trim().toLowerCase(),day=getDayRecord(date),marked=workers.filter(w=>w.active&&['present','worked','absent'].includes(day.records?.[w.id]?.status)),results=query.length<2?[]:workers.filter(w=>w.active&&!marked.some(item=>item.id===w.id)&&[w.name,w.idNumber,w.employeeNo].some(value=>String(value||'').toLowerCase().includes(query))).slice(0,15),all=workers.filter(w=>w.active),present=marked.filter(w=>['present','worked'].includes(day.records[w.id]?.status)).length,absent=marked.filter(w=>day.records[w.id]?.status==='absent').length,summary=document.getElementById('supervisorSummary'),searchBox=document.getElementById('supervisorSearchResults'),table=document.getElementById('supervisorTable');if(summary)summary.innerHTML=`<div class="summary-card"><strong>${all.length}</strong><span>Expected</span></div><div class="summary-card"><strong>${present}</strong><span>Marked present</span></div><div class="summary-card"><strong>${absent}</strong><span>Marked absent</span></div><div class="summary-card"><strong>${marked.length}</strong><span>Marked total</span></div>`;if(searchBox)searchBox.innerHTML=query.length<2?'':results.map(w=>`<button class="worker-search-result" onclick="markSupervisorPresent(${w.id})"><span><strong>${esc(w.name)}</strong><small>${esc(w.idNumber||w.employeeNo||'')}</small></span><b>Mark present</b></button>`).join('')||'<div class="empty">No matching unmarked worker.</div>';if(table)table.innerHTML=marked.map(w=>{const r=day.records[w.id],state=portalStatus(r);return `<tr><td><input class="supervisor-select" type="checkbox" value="${w.id}"></td><td><strong>${esc(w.name)}</strong></td><td>${esc(w.idNumber||w.employeeNo||'')}</td><td><span class="status status-${state==='present'||state==='worked'?'worked':state==='absent'?'absent':'pending'}">${esc(state)}</span></td><td>${Number(r.hours||0)}</td><td>${Number(r.overtime||0)}</td><td><button class="secondary" onclick="editSupervisorRecord(${w.id},'${date}')">Edit</button> <button class="danger" onclick="cancelSupervisorRecord(${w.id},'${date}')">Cancel</button></td></tr>`}).join('')||'<tr><td colspan="7"><div class="empty">Search for a worker above to begin marking attendance.</div></td></tr>';}
renderSupervisorPortal=renderSupervisorAttendanceOnly;
function renderWorkerPortal(){const profile=window.lfCurrentProfile||{},workerId=profile.worker_id||profile.workerId;const worker=workers.find(w=>Number(w.id)===Number(workerId))||workers.find(w=>w.id===Number(document.body.dataset.workerId));const from=document.getElementById('workerPortalFrom')?.value||'0000-01-01',to=document.getElementById('workerPortalTo')?.value||'9999-12-31',status=document.getElementById('workerPortalStatus')?.value||'all',records=worker?Object.entries(attendance).flatMap(([date,day])=>{const r=day.records?.[worker.id];return r?[{date,r}]:[]}).filter(x=>x.date>=from&&x.date<=to&& (status==='all'||portalStatus(x.r)===status)).sort((a,b)=>b.date.localeCompare(a.date)):[],present=records.filter(x=>portalStatus(x.r)==='present').length,hours=records.reduce((n,x)=>n+Number(x.r.hours||0),0),ot=records.reduce((n,x)=>n+Number(x.r.overtime||0),0);const summary=document.getElementById('workerPortalSummary');if(summary)summary.innerHTML=`<div class="summary-card"><strong>${present}</strong><span>Present days</span></div><div class="summary-card"><strong>${records.filter(x=>portalStatus(x.r)==='absent').length}</strong><span>Absent days</span></div><div class="summary-card"><strong>${hours}</strong><span>Hours worked</span></div><div class="summary-card"><strong>${ot}</strong><span>Overtime</span></div>`;const table=document.getElementById('workerPortalTable');if(table)table.innerHTML=worker?records.map(x=>`<tr><td>${x.date}</td><td>${esc(worker.department)}</td><td>${esc(worker.designation||'—')}</td><td>${esc(portalStatus(x.r))}</td><td>${Number(x.r.hours||0)}</td><td>${Number(x.r.overtime||0)}</td><td><button class="secondary" onclick="raiseJtsDispute(${worker.id},'${x.date}')">Dispute</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No attendance records found.</div></td></tr>':'<tr><td colspan="7"><div class="empty">Your worker profile is not linked yet.</div></td></tr>';}
function statusClass(s){return s==="Pending"?"status-pending":s==="Approved"?"status-approved":s==="Allocated"?"status-allocated":s==="Cancelled"?"status-cancelled":s==="Completed"?"status-approved":"status-submitted"}
function renderRequests(){const filter=document.getElementById("requestStatusFilter").value;const table=document.getElementById("requestsTable");table.innerHTML="";const rows=labourRequests.filter(r=>filter==="all"||r.status===filter);if(!rows.length){table.innerHTML='<tr><td colspan="9"><div class="empty">No labour requests found.</div></td></tr>';return}rows.forEach(r=>{const c=clientById(r.clientId);const allocated=r.allocatedWorkerIds?.length||0;let actions=`<button class="secondary" onclick="editRequest(${r.id})">Edit</button>`;if(r.status==="Pending")actions+=` <button class="success" onclick="approveRequest(${r.id})">Approve</button>`;if(["Approved","Allocated"].includes(r.status))actions+=` <button class="primary" onclick="openAllocationModal(${r.id})">Allocate</button>`;if(!["Completed","Cancelled"].includes(r.status))actions+=` <button class="danger" onclick="cancelRequest(${r.id})">Cancel</button>`;if(r.status==="Allocated")actions+=` <button class="success" onclick="completeRequest(${r.id})">Complete</button>`;table.innerHTML+=`<tr><td><strong>${esc(r.requestNo)}</strong><br><small class="muted">${formatDateTime(r.createdAt)}</small></td><td>${esc(c?.name||"—")}</td><td>${esc(r.department)}</td><td>${esc(r.classification)}</td><td>${r.workersRequired}<br><small class="muted">${allocated} allocated</small></td><td>${esc(r.startDate)}</td><td>${r.duration} day(s)</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td>${actions}</td></tr>`})}
function openRequestModal(){document.getElementById("editingRequestId").value="";document.getElementById("requestModalTitle").textContent="New Labour Request";populateFilters();document.getElementById("requestClient").value=clients.find(c=>c.active)?.id||"";document.getElementById("requestWorkers").value=1;document.getElementById("requestClassification").value="Skilled";document.getElementById("requestStartDate").value=today();document.getElementById("requestDuration").value=1;document.getElementById("requestShift").value="Day";document.getElementById("requestNotes").value="";document.getElementById("requestModal").classList.add("show")}
function editRequest(id){const r=requestById(id);if(!r)return;openRequestModal();document.getElementById("editingRequestId").value=id;document.getElementById("requestModalTitle").textContent=`Edit ${r.requestNo}`;document.getElementById("requestClient").value=r.clientId;document.getElementById("requestDepartment").value=r.department;document.getElementById("requestWorkers").value=r.workersRequired;document.getElementById("requestClassification").value=r.classification;document.getElementById("requestStartDate").value=r.startDate;document.getElementById("requestDuration").value=r.duration;document.getElementById("requestShift").value=r.shift;document.getElementById("requestNotes").value=r.notes||""}
function saveRequest(){const id=document.getElementById("editingRequestId").value;const clientId=Number(document.getElementById("requestClient").value);const department=document.getElementById("requestDepartment").value;const workersRequired=Number(document.getElementById("requestWorkers").value);const classification=document.getElementById("requestClassification").value;const startDate=document.getElementById("requestStartDate").value;const duration=Number(document.getElementById("requestDuration").value);const shift=document.getElementById("requestShift").value;const notes=document.getElementById("requestNotes").value.trim();if(!clientId||!department||workersRequired<1||!startDate||duration<1){alert("Complete the required request details.");return}if(id){const r=requestById(id);if(r){r.clientId=clientId;r.department=department;r.workersRequired=workersRequired;r.classification=classification;r.startDate=startDate;r.duration=duration;r.shift=shift;r.notes=notes;showToast(`${r.requestNo} updated.`)}}else{const r={id:Date.now(),requestNo:requestNo(),clientId,department,workersRequired,classification,startDate,duration,shift,notes,status:"Pending",allocatedWorkerIds:[],createdAt:new Date().toISOString()};labourRequests.push(r);showToast(`${r.requestNo} created.`)}saveData();closeModal("requestModal");renderRequests();renderDashboard()}
function approveRequest(id){const r=requestById(id);if(!r)return;r.status="Approved";saveData();renderRequests();renderDashboard();showToast(`${r.requestNo} approved.`)}
function cancelRequest(id){const r=requestById(id);if(!r)return;if(!confirm(`Cancel ${r.requestNo}?`))return;r.status="Cancelled";saveData();renderRequests();renderDashboard();showToast(`${r.requestNo} cancelled.`)}
function completeRequest(id){const r=requestById(id);if(!r)return;r.status="Completed";saveData();renderRequests();renderDashboard();showToast(`${r.requestNo} completed.`)}
function openAllocationModal(id){const r=requestById(id);if(!r)return;if(r.status!=="Approved"&&r.status!=="Allocated"){alert("Approve the request before allocation.");return}document.getElementById("allocationRequestId").value=id;const c=clientById(r.clientId);document.getElementById("allocationSummary").innerHTML=`<strong>${esc(r.requestNo)}</strong> — ${esc(c?.name||"Unknown client")} · ${esc(r.department)} · ${r.workersRequired} required · ${r.allocatedWorkerIds?.length||0} currently allocated`;const picker=document.getElementById("workerPicker");picker.innerHTML="";const eligible=workers.filter(w=>w.active&&(r.classification==="Any"||w.classification===r.classification));if(!eligible.length){picker.innerHTML='<div class="empty">No eligible active workers found.</div>'}else eligible.forEach(w=>{const checked=(r.allocatedWorkerIds||[]).includes(w.id);picker.innerHTML+=`<label class="worker-option"><input type="checkbox" value="${w.id}" ${checked?"checked":""}><span><strong>${esc(w.employeeNo)} — ${esc(w.name)}</strong><small>${esc(w.department)} · ${esc(w.classification)}</small></span></label>`});document.getElementById("allocationModal").classList.add("show")}
function saveAllocation(){const r=requestById(Number(document.getElementById("allocationRequestId").value));if(!r)return;const ids=[...document.querySelectorAll("#workerPicker input:checked")].map(x=>Number(x.value));if(ids.length>r.workersRequired){alert(`This request requires only ${r.workersRequired} worker(s).`);return}r.allocatedWorkerIds=ids;r.status=ids.length?"Allocated":"Approved";ids.forEach(id=>{const w=workers.find(x=>x.id===id);if(w){w.client=clientById(r.clientId)?.name||"";w.assignment=`${r.requestNo} — ${r.department}`;w.deploymentStart=r.startDate;w.department=r.department}});saveData();closeModal("allocationModal");renderRequests();renderWorkers();renderDashboard();showToast(`${ids.length} worker(s) allocated to ${r.requestNo}.`)}
function renderAttendance(){const date=document.getElementById("attendanceDate").value||today(),filter=document.getElementById("departmentFilter").value,day=getDayRecord(date),table=document.getElementById("attendanceTable");table.innerHTML="";let worked=0,absent=0,missing=0,overtime=0;workers.filter(w=>w.active).filter(w=>filter==="all"||w.department===filter).forEach(w=>{const r=getAttendance(date,w.id);if(r.status==="worked")worked++;else if(r.status==="absent")absent++;else missing++;overtime+=Number(r.overtime)||0;const regular=r.status==="worked"?w.rate:0,ot=Number(r.overtime||0)*w.otRate,total=regular+ot,locked=day.submitted||day.approved;table.innerHTML+=`<tr><td><strong>${esc(w.name)}</strong><br><small class="muted">${esc(w.employeeNo)}</small></td><td>${esc(w.department)}</td><td>${esc(w.classification)}</td><td>${money(w.rate)}</td><td><select ${locked?"disabled":""} onchange="changeAttendanceStatus('${date}',${w.id},this.value)"><option value="pending" ${r.status==="pending"?"selected":""}>Missing</option><option value="worked" ${r.status==="worked"?"selected":""}>Worked</option><option value="absent" ${r.status==="absent"?"selected":""}>Absent</option></select></td><td><input type="number" min="0" step="0.5" value="${r.overtime}" ${locked?"disabled":""} onchange="changeOvertime('${date}',${w.id},this.value)"></td><td>${money(ot)}</td><td><strong>${money(total)}</strong></td></tr>`});document.getElementById("workedCount").textContent=worked;document.getElementById("absentCount").textContent=absent;document.getElementById("missingCount").textContent=missing;document.getElementById("overtimeCount").textContent=overtime;saveData()}
function changeAttendanceStatus(date,id,status){const day=getDayRecord(date);if(day.submitted||day.approved)return;getAttendance(date,id).status=status;localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderAttendance();renderDashboard()}
function changeOvertime(date,id,hours){const day=getDayRecord(date);if(day.submitted||day.approved)return;getAttendance(date,id).overtime=Math.max(0,Number(hours)||0);localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderAttendance()}
function markAllWorked(){const date=document.getElementById("attendanceDate").value||today(),day=getDayRecord(date);if(day.submitted||day.approved){alert("This attendance has already been submitted or approved.");return}workers.filter(w=>w.active).forEach(w=>getAttendance(date,w.id).status="worked");localStorage.setItem('labourforce_attendance_dirty','1');saveData();renderAttendance();renderDashboard();showToast("All active workers marked as worked.")}
function submitAttendance(){const date=document.getElementById("attendanceDate").value||today(),day=getDayRecord(date);const missing=workers.filter(w=>w.active).filter(w=>getAttendance(date,w.id).status==="pending");if(missing.length){alert(`${missing.length} worker(s) still have missing attendance.`);return}if(day.submitted){alert("Attendance has already been submitted.");return}day.submitted=true;day.status="submitted";day.submittedAt=new Date().toISOString();saveData();renderAttendance();renderApproval();showToast("Attendance submitted for supervisor approval.")}
function renderApproval(){const date=document.getElementById("approvalDate").value||today(),department=document.getElementById("approvalDepartment").value,day=getDayRecord(date),table=document.getElementById("approvalTable");table.innerHTML="";workers.filter(w=>w.active).filter(w=>department==="all"||w.department===department).forEach(w=>{const r=getAttendance(date,w.id),regular=r.status==="worked"?w.rate:0,ot=Number(r.overtime||0)*w.otRate,total=regular+ot;const a=day.approved?"Approved":day.submitted?"Pending":"Not Submitted";table.innerHTML+=`<tr><td><strong>${esc(w.name)}</strong><br><small class="muted">${esc(w.employeeNo)}</small></td><td>${esc(w.department)}</td><td><span class="status ${r.status==="worked"?"status-worked":r.status==="absent"?"status-absent":"status-missing"}">${r.status==="worked"?"Worked":r.status==="absent"?"Absent":"Missing"}</span></td><td>${r.overtime||0}</td><td>${money(total)}</td><td><span class="status ${day.approved?"status-approved":day.submitted?"status-submitted":"status-missing"}">${a}</span></td></tr>`});document.getElementById("approvalTitle").textContent=day.approved?"Attendance Approved":day.submitted?"Attendance Awaiting Approval":"Attendance Not Submitted";document.getElementById("approvalDescription").textContent=day.approved?`Approved on ${formatDateTime(day.approvedAt)}`:day.submitted?`Submitted on ${formatDateTime(day.submittedAt)}`:"Attendance must be submitted before it can be approved."}
function approveAttendance(){const date=document.getElementById("approvalDate").value||today(),day=getDayRecord(date);if(!day.submitted){alert("Attendance must be submitted before approval.");return}if(day.approved){alert("Attendance is already approved.");return}const missing=workers.filter(w=>w.active).filter(w=>getAttendance(date,w.id).status==="pending");if(missing.length){alert("Attendance contains missing records.");return}day.approved=true;day.status="approved";day.approvedAt=new Date().toISOString();saveData();renderApproval();renderAttendance();renderDashboard();showToast("Attendance approved successfully.")}
function renderWorkers(){const table=document.getElementById("workersTable"),search=(document.getElementById("workerSearch").value||"").toLowerCase(),department=document.getElementById("workerDepartmentFilter").value;table.innerHTML="";const filtered=workers.filter(w=>(w.name||"").toLowerCase().includes(search)||(w.employeeNo||"").toLowerCase().includes(search)||(w.idNumber||"").toLowerCase().includes(search)).filter(w=>department==="all"||w.department===department);if(!filtered.length){table.innerHTML='<tr><td colspan="9"><div class="empty">No workers found.</div></td></tr>';return}filtered.forEach(w=>{const deployment=w.client?`${esc(w.client)}<br><small class="muted">${esc(w.assignment||"")}</small>`:'<span class="muted">Unassigned</span>';const canEdit=canManageWorkerMasterData();const editBtn=canEdit?`<button class="secondary" onclick="editWorker(${w.id})">Edit</button>`:`<button class="secondary" onclick="reportJtsCorrection(${w.id})">Request change</button>`;const stateBtn=canEdit?`<button class="${w.active?"danger":"success"}" onclick="toggleWorker(${w.id})">${w.active?"Deactivate":"Activate"}</button>`:'<span class="muted">View only</span>';table.innerHTML+=`<tr><td><strong>${esc(w.employeeNo)}</strong></td><td><strong>${esc(w.name)}</strong><br><small class="muted">${esc(w.idNumber||"ID not set")} · Joined: ${esc(w.joinDate||"—")}</small></td><td>${esc(w.department)}</td><td>${esc(w.classification)}</td><td>${money(w.rate)}</td><td>${money(w.otRate)}</td><td>${deployment}</td><td><span class="status ${w.active?"status-worked":"status-absent"}">${w.active?"Active":"Inactive"}</span></td><td>${editBtn} <button class="primary" onclick="openDeploymentModal(${w.id})">Deploy</button> ${stateBtn}</td></tr>`})}
function visibleWorkers(){const search=(document.getElementById("workerSearch")?.value||"").toLowerCase(),department=document.getElementById("workerDepartmentFilter")?.value||"all";return workers.filter(w=>(w.name||"").toLowerCase().includes(search)||(w.employeeNo||"").toLowerCase().includes(search)||(w.idNumber||"").toLowerCase().includes(search)).filter(w=>department==="all"||w.department===department)}
function renderWorkersBulk(){const table=document.getElementById("workersTable"),rows=visibleWorkers();if(!table)return;table.innerHTML="";if(!rows.length){table.innerHTML='<tr><td colspan="10"><div class="empty">No workers found.</div></td></tr>';return;}const selected=new Set([...document.querySelectorAll(".worker-select:checked")].map(input=>Number(input.value)));rows.forEach(w=>{const deployment=w.client?`${esc(w.client)}<br><small class="muted">${esc(w.assignment||"")}</small>`:'<span class="muted">Unassigned</span>';const editBtn=canManageWorkerMasterData()?`<button class="secondary" onclick="editWorker(${w.id})">Edit</button>`:`<button class="secondary" onclick="reportJtsCorrection(${w.id})">Request change</button>`;table.innerHTML+=`<tr><td><input class="worker-select" type="checkbox" value="${w.id}" ${selected.has(Number(w.id))?"checked":""} onchange="updateWorkerSelection()"></td><td><strong>${esc(w.employeeNo)}</strong></td><td><strong>${esc(w.name)}</strong><br><small class="muted">${esc(w.idNumber||"ID not set")} · ${esc(w.joinDate||"—")}</small></td><td>${esc(w.department)}</td><td>${esc(w.designation||w.classification||"")}</td><td>${money(w.rate)}</td><td>${money(w.otRate)}</td><td>${deployment}</td><td><span class="status ${w.active?"status-worked":"status-absent"}">${w.active?"Active":"Inactive"}</span></td><td>${editBtn} <button class="primary" onclick="openDeploymentModal(${w.id})">Move</button></td></tr>`});updateWorkerSelection();}
function updateWorkerSelection(){const selected=document.querySelectorAll(".worker-select:checked").length,count=document.getElementById("workerSelectionCount");if(count)count.textContent=`${selected} selected`;}
function toggleAllWorkers(checked){document.querySelectorAll(".worker-select").forEach(input=>input.checked=checked);updateWorkerSelection();}
function applyWorkerBulkAction(){if(!canManageWorkerMasterData()){showToast("Only accountant / HR can apply worker changes.");return;}const ids=[...document.querySelectorAll(".worker-select:checked")].map(input=>Number(input.value)),action=document.getElementById("workerBulkAction")?.value;if(!ids.length){showToast("Select at least one worker.");return;}if(!action){showToast("Choose a bulk action first.");return;}let value;if(action==='department'){value=prompt(`Move ${ids.length} worker(s) to which department?`,departments[0]?.name||'');if(value===null)return;value=value.trim();if(!departments.some(d=>d.name.toLowerCase()===value.toLowerCase())){showToast("Department not found. Add it first.");return;}ids.forEach(id=>{const w=workers.find(worker=>Number(worker.id)===id);if(w)w.department=value;});}else if(action==='designation'){value=prompt(`Assign which designation to ${ids.length} worker(s)?`,"");if(value===null||!value.trim())return;ids.forEach(id=>{const w=workers.find(worker=>Number(worker.id)===id);if(w)w.designation=value.trim();});}else if(action==='rates'){const rate=prompt('Daily rate (KSh):','');if(rate===null)return;const otRate=prompt('OT hourly rate (KSh):','');if(otRate===null)return;if(Number(rate)<=0||Number(otRate)<=0){showToast('Rates must be greater than zero.');return;}ids.forEach(id=>{const w=workers.find(worker=>Number(worker.id)===id);if(w){w.rate=Number(rate);w.otRate=Number(otRate);}});}else ids.forEach(id=>{const w=workers.find(worker=>Number(worker.id)===id);if(w)w.active=action==='activate';});saveData();renderWorkersBulk();renderDashboard();showToast(`Updated ${ids.length} worker(s).`);}
function openWorkerModal(){if(!canManageWorkerMasterData()){showToast("Only accountant / HR can edit worker master data.");return;}document.getElementById("editingWorkerId").value="";document.getElementById("workerModalTitle").textContent="Add Worker";populateFilters();document.getElementById("workerNo").value=employeeNo();document.getElementById("workerName").value="";document.getElementById("workerIdNumber").value="";document.getElementById("workerDesignation").value="";document.getElementById("workerPhone").value="";document.getElementById("workerRate").value="";document.getElementById("workerOtRate").value="";document.getElementById("workerJoinDate").value=today();document.getElementById("workerModal").classList.add("show")}
function editWorker(id){if(!canManageWorkerMasterData()){showToast("Only accountant / HR can edit worker master data.");return;}const w=workers.find(x=>x.id===id);if(!w)return;openWorkerModal();document.getElementById("editingWorkerId").value=id;document.getElementById("workerModalTitle").textContent="Edit Worker";document.getElementById("workerNo").value=w.employeeNo;document.getElementById("workerName").value=w.name;document.getElementById("workerIdNumber").value=w.idNumber||"";document.getElementById("workerDesignation").value=w.designation||"";document.getElementById("workerPhone").value=w.phone||"";document.getElementById("workerDepartment").value=w.department;document.getElementById("workerClassification").value=w.classification;document.getElementById("workerRate").value=w.rate;document.getElementById("workerOtRate").value=w.otRate;document.getElementById("workerJoinDate").value=w.joinDate||today()}
function saveWorker(){if(!canManageWorkerMasterData()){showToast("Only accountant / HR can edit worker master data.");return;}const id=document.getElementById("editingWorkerId").value,name=document.getElementById("workerName").value.trim(),department=document.getElementById("workerDepartment").value,designation=document.getElementById("workerDesignation").value.trim(),idNumber=document.getElementById("workerIdNumber").value.trim(),phone=document.getElementById("workerPhone").value.trim(),classification=document.getElementById("workerClassification").value,rate=Number(document.getElementById("workerRate").value),otRate=Number(document.getElementById("workerOtRate").value),joinDate=document.getElementById("workerJoinDate").value;if(!name||!department||!classification||rate<=0||otRate<=0){alert("Complete all worker details.");return}if(id){const w=workers.find(x=>x.id===Number(id));if(!w)return;Object.assign(w,{name,department,designation,idNumber,phone,classification,rate,otRate,joinDate});showToast("Worker updated successfully.")}else{const employeeNo=document.getElementById("workerNo").value;workers.push({id:Date.now(),employeeNo,idNumber,designation,phone,name,department,classification,rate,otRate,joinDate,active:true,client:"",assignment:"",deploymentStart:""});showToast(`${employeeNo} created successfully.`)}saveData();closeModal("workerModal");renderWorkers();renderDashboard()}
function toggleWorker(id){if(!canManageWorkerMasterData()){showToast("Only accountant / HR can change worker activation state.");return;}const w=workers.find(x=>x.id===id);if(!w)return;w.active=!w.active;saveData();renderWorkers();renderDashboard();showToast(w.active?`${w.employeeNo} activated.`:`${w.employeeNo} deactivated.`)}
function openDeploymentModal(id){const w=workers.find(x=>x.id===id);if(!w)return;populateFilters();document.getElementById("deploymentWorkerId").value=id;document.getElementById("deploymentWorkerName").value=`${w.employeeNo} — ${w.name}`;document.getElementById("deploymentClient").value="";document.getElementById("deploymentDepartment").value=w.department;document.getElementById("deploymentStartDate").value=today();document.getElementById("deploymentAssignment").value="";document.getElementById("deploymentRequest").value="";document.getElementById("deploymentModal").classList.add("show")}
function saveDeployment(){const id=Number(document.getElementById("deploymentWorkerId").value),w=workers.find(x=>x.id===id),clientId=Number(document.getElementById("deploymentClient").value),department=document.getElementById("deploymentDepartment").value,start=document.getElementById("deploymentStartDate").value,assignment=document.getElementById("deploymentAssignment").value.trim(),requestId=Number(document.getElementById("deploymentRequest").value)||null;if(!w||!clientId||!department||!start){alert("Select a client, department and start date.");return}w.client=clientById(clientId)?.name||"";w.department=department;w.assignment=assignment||"Direct deployment";w.deploymentStart=start;if(requestId){const r=requestById(requestId);if(r&&!r.allocatedWorkerIds.includes(w.id))r.allocatedWorkerIds.push(w.id);if(r&&r.allocatedWorkerIds.length)r.status="Allocated"}saveData();closeModal("deploymentModal");renderWorkers();renderRequests();showToast(`${w.employeeNo} deployed successfully.`)}
function renderClients(){const table=document.getElementById("clientsTable");table.innerHTML="";clients.forEach(c=>{const reqs=labourRequests.filter(r=>r.clientId===c.id&&!['Completed','Cancelled'].includes(r.status));const allocated=new Set(reqs.flatMap(r=>r.allocatedWorkerIds||[])).size;table.innerHTML+=`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.contact||"—")}</td><td>${esc(c.phone||"—")}</td><td>${reqs.length}</td><td>${allocated}</td><td><span class="status ${c.active?"status-worked":"status-absent"}">${c.active?"Active":"Inactive"}</span></td><td><button class="secondary" onclick="editClient(${c.id})">Edit</button> <button class="${c.active?"danger":"success"}" onclick="toggleClient(${c.id})">${c.active?"Deactivate":"Activate"}</button></td></tr>`})}
function openClientModal(){document.getElementById("editingClientId").value="";document.getElementById("clientModalTitle").textContent="Add Client";document.getElementById("clientName").value="";document.getElementById("clientContact").value="";document.getElementById("clientPhone").value="";document.getElementById("clientModal").classList.add("show")}
function editClient(id){const c=clientById(id);if(!c)return;openClientModal();document.getElementById("editingClientId").value=id;document.getElementById("clientModalTitle").textContent="Edit Client";document.getElementById("clientName").value=c.name;document.getElementById("clientContact").value=c.contact||"";document.getElementById("clientPhone").value=c.phone||""}
function saveClient(){const id=document.getElementById("editingClientId").value,name=document.getElementById("clientName").value.trim(),contact=document.getElementById("clientContact").value.trim(),phone=document.getElementById("clientPhone").value.trim();if(!name){alert("Enter the company name.");return}if(id){const c=clientById(id);Object.assign(c,{name,contact,phone});showToast("Client updated.")}else{clients.push({id:Date.now(),name,contact,phone,active:true});showToast("Client added.")}saveData();closeModal("clientModal");populateClientSelects();renderClients();renderDashboard()}
function toggleClient(id){const c=clientById(id);if(!c)return;c.active=!c.active;saveData();populateClientSelects();renderClients();showToast(c.active?`${c.name} activated.`:`${c.name} deactivated.`)}
function renderDepartments(){const table=document.getElementById("departmentsTable");table.innerHTML="";departments.forEach(d=>{const count=workers.filter(w=>w.active&&w.department===d.name).length;table.innerHTML+=`<tr><td><strong>${esc(d.name)}</strong></td><td>${esc(d.parent||"—")}</td><td>${count}</td><td>${d.rate?money(d.rate):'Worker rate'}</td><td>${d.otRate?money(d.otRate):'Worker rate'}</td></tr>`})}
function openDepartmentModal(){populateFilters();document.getElementById("departmentName").value="";document.getElementById("departmentRate").value="";document.getElementById("departmentOtRate").value="";document.getElementById("departmentModal").classList.add("show")}
function saveDepartment(){const name=document.getElementById("departmentName").value.trim(),parent=document.getElementById("departmentParent").value,rate=Number(document.getElementById("departmentRate").value)||0,otRate=Number(document.getElementById("departmentOtRate").value)||0;if(!name){alert("Enter a department name.");return}const existing=departments.find(d=>d.name.toLowerCase()===name.toLowerCase());if(existing){existing.rate=rate;existing.otRate=otRate;showToast("Department wage defaults updated.");}else departments.push({name,parent,rate,otRate});saveData();closeModal("departmentModal");populateFilters();renderDepartments();showToast(existing?"Department wage defaults updated.":"Department added.")}
function renderPayroll(){const period=document.getElementById("payrollPeriod").value;let regular=0,overtime=0,workersPaid=0;const table=document.getElementById("payrollTable");table.innerHTML="";workers.filter(w=>w.active).forEach(w=>{let days=0,otHours=0;Object.entries(attendance).forEach(([date,day])=>{const n=Number(date.split("-")[2]);const include=period==="first"?n>=1&&n<=15:n>=16;if(!include||!day.approved)return;const r=day.records?.[w.id];if(r?.status==="worked"){days++;otHours+=Number(r.overtime)||0}});const reg=days*w.rate,ot=otHours*w.otRate,gross=reg+ot;if(days)workersPaid++;regular+=reg;overtime+=ot;table.innerHTML+=`<tr><td>${esc(w.name)}</td><td>${days}</td><td>${money(w.rate)}</td><td>${money(reg)}</td><td>${otHours}</td><td>${money(ot)}</td><td><strong>${money(gross)}</strong></td></tr>`});document.getElementById("payrollWorkers").textContent=workersPaid;document.getElementById("payrollRegular").textContent=money(regular);document.getElementById("payrollOvertime").textContent=money(overtime);document.getElementById("payrollGross").textContent=money(regular+overtime)}
function calculatePayroll(){renderPayroll();payroll.lastCalculated=new Date().toISOString();saveData();showToast("Payroll calculated from approved attendance.")}
function renderReports(){document.getElementById("reportWorkers").textContent=workers.filter(w=>w.active).length;document.getElementById("reportClients").textContent=clients.filter(c=>c.active).length;document.getElementById("reportDepartments").textContent=departments.length;const d=getDayRecord(today());document.getElementById("reportAttendance").textContent=d.approved?"Approved":d.submitted?"Submitted":"Pending"}
function JtsWorkerById(id){return workers.find(w=>Number(w.id)===Number(id))||null}
function ensureJtsWorkerSelect(){const sel=document.getElementById("jtsHistoryWorker");if(!sel)return;sel.innerHTML="";workers.filter(w=>w.active).forEach(w=>{const label=`${w.name} (${w.idNumber||w.employeeNo||w.id})`;const opt=document.createElement("option");opt.value=String(w.id);opt.textContent=label;sel.appendChild(opt)});if(!sel.value && workers.length){sel.value=String(workers[0].id)}}
function getJtsRecordFor(date,workerId){const day=getDayRecord(date);if(!day.records[workerId])day.records[workerId]={status:"pending",hours:0,overtime:0};return day.records[workerId]}
function normalizeText(value){return String(value ?? "").replace(/\s+/g," ").trim()}
function numberFromCell(value){const n = Number(String(value ?? '').replace(/[^0-9.\-]/g, ''));
	return Number.isFinite(n) ? n : 0;}
function parseJtsWorkbook(file){
	if(!file){showToast('Please choose the JTS Excel workbook first.');return;}
	const reader=new FileReader();
	reader.onload=function(e){
		try{
			const workbook=XLSX.read(new Uint8Array(e.target.result),{type:'array'}), importedWorkers=[], seen=new Set();
			workbook.SheetNames.forEach(sheetName=>{
				const rows=XLSX.utils.sheet_to_json(workbook.Sheets[sheetName],{header:1,blankrows:false,defval:''});
				const headerIndex=rows.findIndex(row=>row.some(cell=>/STAFF NO|Payroll No\.|ID NO/i.test(normalizeText(cell))));
				if(headerIndex<0)return;
				const headers=rows[headerIndex].map(cell=>normalizeText(cell).toLowerCase());
				const col=(...names)=>{const index=headers.findIndex(header=>names.some(name=>header===name||header.includes(name)));return index<0?null:index;};
				const staffCol=col('staff no','payroll no'),kraCol=col('kra pin'),nssfCol=col('nssf'),shifCol=col('shif/nhif','nhif/shif'),accountCol=col('acc. no','account'),idCol=col('id no'),phoneCol=col('phone'),deptCol=col('department'),designationCol=col('designation','position'),nameCol=col('name','site staff'),dailyCol=col('daily rate','basic pay'),hourlyCol=col('hourly rate');
				const dayCols=[]; headers.forEach((header,index)=>{const day=Number(header);if(day>=1&&day<=31)dayCols.push({index,day});});
				for(let rowIndex=headerIndex+1;rowIndex<rows.length;rowIndex++){
					const row=rows[rowIndex]||[], name=normalizeText(row[nameCol]);
					if(!name||name.toLowerCase().includes('total'))continue;
					const department=normalizeText(row[deptCol])||sheetName.split(',')[0].trim()||'Operations', designation=normalizeText(row[designationCol])||'Casual', employeeNo=normalizeText(row[staffCol])||`WK${String(importedWorkers.length+1).padStart(3,'0')}`, idNumber=normalizeText(row[idCol]), key=`${employeeNo}|${name}|${idNumber}`;
					if(seen.has(key))continue; seen.add(key);
					const worker={id:Date.now()+importedWorkers.length+1,employeeNo,kraPin:normalizeText(row[kraCol]),nssfNumber:normalizeText(row[nssfCol]),shifNumber:normalizeText(row[shifCol]),accountNumber:normalizeText(row[accountCol]),idNumber,phone:normalizeText(row[phoneCol]),name,department,designation,classification:/bagging|casual|kilifi/i.test(sheetName)?'Casual':'Staff',rate:numberFromCell(row[dailyCol]),otRate:numberFromCell(row[hourlyCol]),joinDate:'2026-07-01',active:true,client:'',assignment:'',deploymentStart:'',workbookSource:sheetName};
					importedWorkers.push(worker);
					dayCols.forEach(({index,day})=>{const hours=numberFromCell(row[index]);if(hours<=0)return;const date=`2026-07-${String(day).padStart(2,'0')}`,record=getAttendance(date,worker.id);record.status='present';record.hours=Math.min(hours,9);record.overtime=Math.max(0,hours-9);});
				}
			});
			if(!importedWorkers.length){alert('No worker records were detected in the workbook.');return;}
			workers=importedWorkers;
			departments=[...new Map(workers.map(worker=>[worker.department,{name:worker.department,parent:''}])).values()];
			localStorage.setItem('labourforce_jts_workbook_imported','true');saveData();populateFilters();renderWorkers();renderDashboard();renderJtsAttendance();renderJtsHistory();renderJtsPayroll();
			showToast(`Imported ${workers.length} workers and July attendance from ${workbook.SheetNames.length} sheets.`);
		}catch(err){console.error(err);alert('The JTS workbook could not be imported. Please check that it is a valid Excel workbook.');}
	};
	reader.readAsArrayBuffer(file);
}
function importJtsWorkbookFromInput(file){parseJtsWorkbook(file)}
renderWorkers=renderWorkersBulk;
function generateJtsRoster(){const date=document.getElementById("jtsDate").value||today();const active=workers.filter(w=>w.active);if(!active.length){showToast("No active workers to roster.");return;}active.forEach(w=>{const record=getJtsRecordFor(date,w.id);record.status=record.status||"pending";record.hours=Number(record.hours||0);record.overtime=Number(record.overtime||0);});saveData();renderJtsAttendance();renderDashboard();showToast(`${active.length} workers added to the ${date} roster.`)}
function setJtsStatus(date,workerId,status){const record=getJtsRecordFor(date,workerId);record.status=status;if(status==="present"){record.hours=Number(record.hours||9)||9;}if(status==="absent"){record.hours=0;record.overtime=0;}saveData();renderJtsAttendance();renderDashboard();}
function changeJtsHours(date,workerId,hours){const record=getJtsRecordFor(date,workerId);record.status=record.status==="present"?"present":record.status==="pending"?"pending":record.status;record.hours=Math.max(0,Number(hours)||0);saveData();renderJtsAttendance();}
function changeJtsOt(date,workerId,hours){const record=getJtsRecordFor(date,workerId);record.overtime=Math.max(0,Number(hours)||0);saveData();renderJtsAttendance();}
function reportJtsCorrection(workerId){const w=JtsWorkerById(workerId);if(!w)return;const note=prompt(`Describe the master-data problem for ${w.name}:`, "");if(note===null)return;const msg=note.trim();if(!msg){showToast("A correction note is required.");return;}jtsState.corrections.push({id:Date.now(),workerId:Number(workerId),issueType:"worker_details",issueText:msg,status:"open",createdAt:new Date().toISOString()});saveData();showToast("Correction sent to admin for resolution.")}
function raiseJtsDispute(workerId,date){const w=JtsWorkerById(workerId);if(!w)return;const note=prompt(`Dispute details for ${w.name} on ${date}:`, "");if(note===null)return;const msg=note.trim();if(!msg){showToast("A dispute note is required.");return;}jtsState.disputes.push({id:Date.now(),workerId:Number(workerId),date, note:msg, status:"pending", createdAt:new Date().toISOString()});saveData();renderJtsHistory();showToast("Dispute flagged for review.")}
function renderJtsAttendance(){const date=document.getElementById("jtsDate").value||today();ensureJtsRosterForDate(date);const table=document.getElementById("jtsAttendanceTable");if(!table)return;table.innerHTML="";const rows=workers.filter(w=>w.active).map(w=>({w,record:getJtsRecordFor(date,w.id)}));const present=rows.filter(r=>r.record.status==="present").length;const absent=rows.filter(r=>r.record.status==="absent").length;const pending=rows.filter(r=>r.record.status==="pending").length;const summary=document.getElementById("jtsSummary");if(summary){summary.innerHTML=`<div class="summary-card"><strong>${rows.length}</strong><span>Active workers</span></div><div class="summary-card"><strong>${present}</strong><span>Present</span></div><div class="summary-card"><strong>${absent}</strong><span>Absent</span></div><div class="summary-card"><strong>${pending}</strong><span>Pending</span></div>`;}if(!rows.length){table.innerHTML='<tr><td colspan="7"><div class="empty">No active workers on the roster.</div></td></tr>';return}rows.forEach(({w,record})=>{const hours=Number(record.hours||0);const ot=Number(record.overtime||0);table.innerHTML+=`<tr><td><strong>${esc(w.name)}</strong><br><small class="muted">${esc(w.idNumber||w.employeeNo||w.id)}</small></td><td>${esc(w.idNumber||w.employeeNo||w.id)}</td><td>${esc(w.department)}</td><td><select onchange="setJtsStatus('${date}', ${w.id}, this.value)" ${canCaptureAttendance()?'':'disabled'}><option value="pending" ${record.status==="pending"?"selected":""}>Pending</option><option value="present" ${record.status==="present"?"selected":""}>Present</option><option value="absent" ${record.status==="absent"?"selected":""}>Absent</option></select></td><td><input type="number" min="0" step="0.5" value="${hours}" onchange="changeJtsHours('${date}', ${w.id}, this.value)" ${canCaptureAttendance() && record.status==="present"?"":"disabled"}></td><td><input type="number" min="0" step="0.5" value="${ot}" onchange="changeJtsOt('${date}', ${w.id}, this.value)" ${canCaptureAttendance() && record.status==="present"?"":"disabled"}></td><td>${canCaptureAttendance()?`<button class="secondary" onclick="reportJtsCorrection(${w.id})">Inform admin</button>`:'<span class="muted">Read-only</span>'}</td></tr>`;});}
function renderJtsHistory(){ensureJtsWorkerSelect();const workerId=Number(document.getElementById("jtsHistoryWorker").value)||workers[0]?.id;const table=document.getElementById("jtsHistoryTable");if(!table)return;const history=Object.entries(attendance).map(([date,day])=>{const rec=day.records&&day.records[workerId]?day.records[workerId]:null;return rec?{date,status:rec.status,hours:Number(rec.hours||0),overtime:Number(rec.overtime||0)}:null}).filter(Boolean).sort((a,b)=>b.date.localeCompare(a.date));const disputes=jtsState.disputes.filter(d=>Number(d.workerId)===Number(workerId));const totalHours=history.reduce((sum,item)=>sum+Number(item.hours||0),0);const worked=history.filter(h=>h.status==="present").length;const summary=document.getElementById("jtsRollup");if(summary){summary.innerHTML=`<div class="summary-card"><strong>${worked}</strong><span>Days worked</span></div><div class="summary-card"><strong>${totalHours}</strong><span>Total hours</span></div><div class="summary-card"><strong>${disputes.filter(d=>d.status==='pending').length}</strong><span>Disputes pending</span></div>`;}table.innerHTML="";if(!history.length){table.innerHTML='<tr><td colspan="5"><div class="empty">No attendance history for this worker yet.</div></td></tr>';return;}history.forEach(item=>{const disputeExists = disputes.some(d => d.date === item.date);table.innerHTML+=`<tr><td>${esc(item.date)}</td><td><span class="status ${item.status==="present"?"status-worked":"status-absent"}">${item.status==="present"?"Worked":"Absent"}</span></td><td>${Number(item.hours||0)}</td><td>${Number(item.overtime||0)}</td><td>${disputeExists?'<span class="status status-pending">Flagged</span>':'<button class="secondary" onclick="raiseJtsDispute('+workerId+',\''+item.date+'\')">Dispute</button>'}</td></tr>`;});}
function calculateJtsPayroll(){const period=document.getElementById("jtsPayrollPeriod").value||"current";let totalNet=0,totalGross=0,totalDeductions=0;const rows=[];workers.filter(w=>w.active).forEach(w=>{let days=0,normalHours=0,otHours=0;Object.entries(attendance).forEach(([date,day])=>{const rec=day.records&&day.records[w.id];if(!rec||!(rec.status==="present"||rec.status==="approved"))return;days++;normalHours+=Number(rec.hours||0);otHours+=Number(rec.overtime||0);});const regularPay=normalHours*(Number(w.rate)||0);const overtimePay=otHours*(Number(w.otRate)||0);const gross=regularPay+overtimePay;const nssf=gross*0.06;const housing=gross*0.015;const shif=gross*0.005;const paye=gross*0.10;const deductions=0;const net=gross-nssf-housing-shif-paye-deductions;totalNet+=net;totalGross+=gross;totalDeductions+=deductions;const review=net<0 || Math.abs(net-(gross-nssf-housing-shif-paye))>1?"Review required":"OK";rows.push({w,days,normalHours,otHours,regularPay,overtimePay,gross,nssf,housing,shif,paye,deductions,net,review});});const summary=document.getElementById("jtsPayrollSummary");if(summary){summary.innerHTML=`<div class="summary-card"><strong>${money(totalGross)}</strong><span>Gross</span></div><div class="summary-card"><strong>${money(totalDeductions)}</strong><span>Deductions</span></div><div class="summary-card"><strong>${money(totalNet)}</strong><span>Net pay</span></div>`;}const table=document.getElementById("jtsPayrollTable");if(!table)return;table.innerHTML="";if(!rows.length){table.innerHTML='<tr><td colspan="8"><div class="empty">No payroll rows for the selected period.</div></td></tr>';return;}rows.forEach(r=>{table.innerHTML+=`<tr><td><strong>${esc(r.w.name)}</strong><br><small class="muted">${esc(r.w.idNumber||r.w.employeeNo||r.w.id)}</small></td><td>${r.days}</td><td>${money(r.regularPay)}</td><td>${money(r.overtimePay)}</td><td>${money(r.gross)}</td><td>${money(r.deductions)}</td><td>${money(r.net)}</td><td><span class="status ${r.review==="OK"?"status-worked":"status-pending"}">${r.review}</span></td></tr>`;});return rows;}
function getJtsPayrollWorkers(){const search=(document.getElementById('jtsPayrollSearch')?.value||'').toLowerCase().trim(),designation=document.getElementById('jtsPayrollDesignation')?.value||'all';return workers.filter(w=>w.active).filter(w=>designation==='all'||w.designation===designation).filter(w=>!search||[w.name,w.employeeNo,w.idNumber,w.nssfNumber,w.department,w.designation].some(value=>String(value||'').toLowerCase().includes(search)))}
const calculateJtsPayrollForAll=calculateJtsPayroll;
function calculateJtsPayrollFiltered(){const rows=getJtsPayrollWorkers().map(w=>{let days=0,otHours=0;Object.entries(attendance).forEach(([date,day])=>{const rec=day.records?.[w.id];if(date.startsWith('2026-07-')&&rec?.status==='present'){days++;otHours+=Number(rec.overtime)||0;}});const department=departments.find(d=>d.name===w.department),dailyRate=Number(w.rate)||Number(department?.rate)||0,otRate=Number(w.otRate)||Number(department?.otRate)||0,normal=days*dailyRate,ot=otHours*otRate,gross=normal+ot,nssf=gross*(jtsDeductionRates.nssf/100),housing=gross*(jtsDeductionRates.housing/100),shif=gross*(jtsDeductionRates.shif/100),paye=gross*(jtsDeductionRates.paye/100),deductions=nssf+housing+shif+paye;return {w,days,normal,ot,gross,deductions,net:gross-deductions};});const gross=rows.reduce((sum,row)=>sum+row.gross,0),deductions=rows.reduce((sum,row)=>sum+row.deductions,0),summary=document.getElementById('jtsPayrollSummary'),table=document.getElementById('jtsPayrollTable');if(summary)summary.innerHTML=`<div class="summary-card"><strong>${money(gross)}</strong><span>Gross</span></div><div class="summary-card"><strong>${money(deductions)}</strong><span>Statutory deductions</span></div><div class="summary-card"><strong>${money(gross-deductions)}</strong><span>Net pay</span></div>`;if(table)table.innerHTML=rows.length?rows.map(row=>`<tr><td><strong>${esc(row.w.name)}</strong><br><small class="muted">${esc(row.w.idNumber||row.w.employeeNo||row.w.id)} · ${esc(row.w.designation||'')}</small></td><td>${row.days}</td><td>${money(row.normal)}</td><td>${money(row.ot)}</td><td>${money(row.gross)}</td><td>${money(row.deductions)}</td><td>${money(row.net)}</td><td><span class="status status-worked">OK</span></td></tr>`).join(''):'<tr><td colspan="8"><div class="empty">No payroll rows for the selected period.</div></td></tr>';}
function populateJtsPayrollFilters(){const select=document.getElementById('jtsPayrollDesignation');if(!select)return;const current=select.value,designations=[...new Set(workers.filter(w=>w.active).map(w=>w.designation).filter(Boolean))].sort();select.innerHTML='<option value="all">All designations</option>'+designations.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');if(designations.includes(current))select.value=current}
function applyJtsDeductionRates(){jtsDeductionRates={nssf:Number(document.getElementById('jtsNssfRate').value)||0,housing:Number(document.getElementById('jtsHousingRate').value)||0,shif:Number(document.getElementById('jtsShifRate').value)||0,paye:Number(document.getElementById('jtsPayeRate').value)||0};saveData();renderJtsPayroll();showToast('Shared deduction percentages applied.');}
function loadJtsDeductionRates(){Object.entries({jtsNssfRate:jtsDeductionRates.nssf,jtsHousingRate:jtsDeductionRates.housing,jtsShifRate:jtsDeductionRates.shif,jtsPayeRate:jtsDeductionRates.paye}).forEach(([id,value])=>{const input=document.getElementById(id);if(input)input.value=value;});}
function renderJtsPayroll(){loadJtsDeductionRates();populateJtsPayrollFilters();calculateJtsPayrollFiltered();}
