function downloadCSV(filename,rows){const csv=rows.map(row=>row.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(",")).join("\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
function exportAttendance(){const date=document.getElementById("attendanceDate").value||today(),rows=[["Employee No.","Worker","Department","Classification","Daily Rate","OT Rate","Status","OT Hours","OT Pay","Total Pay"]];workers.filter(w=>w.active).forEach(w=>{const r=getAttendance(date,w.id),reg=r.status==="worked"?w.rate:0,ot=Number(r.overtime||0)*w.otRate;rows.push([w.employeeNo,w.name,w.department,w.classification,w.rate,w.otRate,r.status,r.overtime,ot,reg+ot])});downloadCSV(`attendance-${date}.csv`,rows)}
